extern "C" void deki_register_all_components(void);   // AllComponentRegistration.gen.cpp
extern "C" void deki_init_package_systems(void);      // AllPackageInit.gen.cpp
extern "C" void deki_shutdown_package_systems(void);  // AllPackageInit.gen.cpp

#include <cstdio>

// Project package registration (generated by Deki Editor for firmware builds).
// On desktop (DEKI_EDITOR), packages are DLLs loaded by PackageLoader — no static registration needed.
#ifndef DEKI_EDITOR
extern "C" void deki_register_project_packages(void);
#endif

